from common import *
import subprocess

if __name__=='__main__':
    register_adapter(__file__)
    contract=BASE/'configs'/f'{PREFIX}-accounts.json'
    fixed={'kind':'conditional_derived_accounts','parent_exp_id':'training-target/horizon-style-p50-20261105-v1','user_request':'查完若无法定位原因，两模型再用真阶梯跑回测，看gap是否收窄。','remaining_question':'Seed3000 repeatability and label-driven trajectory divergence are established; whether the full s5 CAGR gap reproduces and how much is specific to s5 execution remain unmeasured. This fixed-rule comparison addresses that remaining gap, not historical v2 reconstruction.','models':['old-label reconstructed five-seed H20, original settings, first repetition','retained new-label five-seed H20'],'jobs':[['old','s5'],['old','ladder'],['new','ladder']],'control_gate':{'old_reconstructed_s5_cagr_absolute_tolerance':1e-10,'reference':'docs/H20-observed-label-effect.json metrics.previous_p50.account.annualized_return','on_failure':'Stop paired ladder launch; inspect control mismatch. Do not silently relabel reconstructed signals as original.'},'comparison':'Signed old-minus-new and absolute CAGR gaps for s5 and top3/H5 ladder. Report arithmetic-account gaps separately. No direct subtraction of model238/H5 net_ann from accountCAGR. No parameter search.','configs':[fingerprint(BASE/'configs/fixed-s5.yaml'),fingerprint(BASE/'configs/derived-ladder-k3h5.yaml')],'budget':'Three jobs within parent max4 account attempts; one spare only for technical retry. 0 new fits.'}
    assert not contract.exists();write(contract,fixed)
    while True:
        state=read(STATE)
        if state['phase']=='recovered_ensemble_ready':break
        if any(j['status']=='failed' for j in state['jobs']):raise RuntimeError('fit failure')
        if time.time()>state['deadline']:raise RuntimeError('deadline')
        time.sleep(10)
    state['phase']='derived_accounts';write(STATE,state)
    for label,rule in fixed['jobs']:
        log=TMP/f'account-{label}-{rule}.log'
        with log.open('w') as f:r=subprocess.run([sys.executable,'-u',str(TMP/'account.py'),label,rule],stdout=f,stderr=subprocess.STDOUT,cwd=ROOT)
        if r.returncode:raise RuntimeError(f'account failed: {log}')
        if label=='old' and rule=='s5':
            current=read(BASE/'metrics'/f'{PREFIX}-old-s5.json')['ensemble']['full_period']['annualized_return']
            prior=read(BASE/'docs/H20-observed-label-effect.json')['metrics']['previous_p50']['account']['annualized_return']
            check={'reconstructed_cagr':current,'prior_cagr':prior,'absolute_error':abs(current-prior),'tolerance':1e-10,'passed':abs(current-prior)<=1e-10,'account_source':fingerprint(BASE/'metrics'/f'{PREFIX}-old-s5.json')}
            write(BASE/'docs'/f'{PREFIX}-old-account-gate.json',check)
            assert check['passed'],'reconstructed old s5 does not match historical result'
    with (TMP/'report.log').open('w') as f:r=subprocess.run([sys.executable,str(TMP/'report.py')],stdout=f,stderr=subprocess.STDOUT,cwd=ROOT)
    if r.returncode:raise RuntimeError('report generation failed')
    state=read(STATE);state['phase']='publication_pending';write(STATE,state)
    print('Derived accounts and report ready for verification/publication.',flush=True)
